import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const healingPhysicalScenarios={'heal-warrior':'a2-p12-r2c1','heal-magic-1':'a2-p14-r3c1','heal-magic-2':'a2-p14-r3c2','heal-jill-1':'a2-p14-r3c1','heal-jill-2':'a2-p14-r3c2'} as const;
export type HealingPhysicalScenario=keyof typeof healingPhysicalScenarios;
export function isHealingPhysicalScenario(name:string):name is HealingPhysicalScenario{return Object.hasOwn(healingPhysicalScenarios,name);}
export function healingPhysicalMode(name:HealingPhysicalScenario){return {card:healingPhysicalScenarios[name],dedicated:name.startsWith('heal-jill'),warrior:name==='heal-warrior'};}
export function makeHealingPhysicalScenario(name:HealingPhysicalScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;silence?:boolean}={}){
 let s=createGame(players,entropy(),{startingSeat:3});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.owner??'大神官ジル');assignCharacter(s,b,'侍大将のシン');assignCharacter(s,c,'邪祭ウーノス');assignCharacter(s,d,'占星術師のアルセイル');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};for(const stat of ['warrior_level','magic_level'] as const)s.players[a]!.permanent![stat]=20+(options.level??5)-gameStats(s,a)[stat];s.players[a]!.permanent!.spirit=20+6-gameStats(s,a).spirit;
 const card=takeCard(s,a,healingPhysicalScenarios[name]),advance=takeCard(s,a,'a2-p24-r1c2'),fire=takeCard(s,d,'a2-p15-r3c2'),ice=takeCard(s,d,'a2-p12-r2c2'),fate=takeCard(s,c,'命運凶変'),other=takeCard(s,c,card==='a2-p14-r3c1'?'a2-p14-r3c2':'a2-p14-r3c1'),silence=options.silence?takeCard(s,d,'a2-p18-r1c1'):null;for(const id of [a,b,c,d])trimHand(s,id,card,advance,fire,ice,fate,other,...(silence?[silence]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand,dice=Array(100).fill(1)){const input={actorId,command},e={...entropy(),dice},r=transition(s,input,e);if(!r.ok)throw Error(`HEAL_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('HEAL_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('HEAL_IDS');}
 function next(target:string){for(let n=0;n<300;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w){const r=s.rolls?.at(-1),fail=r?.rollerId===a&&['status-resistance','status-recovery'].includes(r.purpose)&&r.stage==='before-roll';act(w.participants[w.cursor]!,{type:'PASS'},Array(100).fill(fail?6:1));}else if(s.phase==='action'){if(id===target)return;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>![card,advance,ice,fate,other,silence].includes(x)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('HEAL_PHASE');}throw Error('HEAL_TURNS');}
 for(const id of [a,b,c,d])act(id,{type:'PASS_SETUP'});act(d,{type:'START_TURN'});act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:fire,targetIds:[a],dedicated:false});next(d);act(d,{type:'ATTACK',cardInstanceId:ice,targetIds:[b],dedicated:false});if(silence){next(d);act(d,{type:'ATTACK',cardInstanceId:silence,targetIds:[a],dedicated:false});}next(a);if(s.players[a]!.damage!==5||s.players[b]!.damage!==4)throw Error('HEAL_DAMAGE');if(silence&&!s.players[a]!.statuses?.some(t=>t.kind==='silenced'))throw Error('HEAL_SILENCE');return s;
}
